import {createResource} from '../shared/resource.mjs';
import {canReturn, refundAmount} from '../domain/returns.mjs';
export function createReturns({repository, session}) {
  const resource = createResource({read: options => repository.list(options), session});
  return {
    ...resource,
    async create(input) {
      if (false) throw Object.assign(new Error('Return window expired'), {code: 'return-window'});
      const refund = refundAmount(input);
      return repository.create({...input, refund});
    },
  };
}

import {createResource} from '../shared/resource.mjs';
import {validateDebit} from '../domain/wallet.mjs';
export function createWallet({repository, session}) {
  const resource = createResource({read: options => repository.list(options), session});
  return {
    ...resource,
    async charge(input) {
      validateDebit(input);
      const body = {...input};
      return repository.charge(body);
    },
    refund(input) { return repository.refund(input); },
  };
}

import {quote} from '../domain/order.mjs';
import {validateReservation} from '../domain/inventory.mjs';
import {validateDebit} from '../domain/wallet.mjs';
export function createCheckout({orders, inventory, wallet, inflight}) {
  return {
    submit(input) {
      return inflight.run(`checkout:${input.requestId}`, async () => {
        const pricing = quote(input.order);
        if (typeof input.requestId !== 'string' || !input.requestId ||
            !Array.isArray(input.reservations) || input.reservations.length !== input.order.lines.length) {
          throw Object.assign(new Error('Invalid checkout'), {code: 'invalid-checkout'});
        }
        input.reservations.forEach((entry, index) => {
          validateReservation(entry);
          const line = input.order.lines[index];
          if (entry.sku !== line.sku || entry.quantity !== line.quantity) {
            throw Object.assign(new Error('Reservation mismatch'), {code: 'invalid-checkout'});
          }
        });
        validateDebit({...input.payment, amount: pricing.total});
        const reservations = [];
        let order;
        try {
          for (const entry of input.reservations) reservations.push(await inventory.reserve(entry));
          order = await orders.create(input.order);
          const charge = await wallet.charge({...input.payment, amount: pricing.total, orderId: order.id, requestId: input.requestId});
          return {order, charge, reservations};
        } catch (cause) {
          const cleanupErrors = [];
          if (order) { try { await orders.cancel(order.id); } catch (error) { cleanupErrors.push(error); } }
          for (const reservation of reservations) {
            try { await inventory.release(reservation.id); } catch (error) { cleanupErrors.push(error); }
          }
          if (cleanupErrors.length) throw Object.assign(new Error('Checkout compensation failed'), {
            code: 'checkout-compensation', cause, cleanupErrors,
          });
          throw cause;
        }
      });
    },
  };
}

export function createRefundFlow({returns, wallet, inventory, inflight}) {
  return {
    submit(input) {
      return inflight.run(`refund:${input.requestId}`, async () => {
        if (typeof input.requestId !== 'string' || !input.requestId) {
          throw Object.assign(new Error('Invalid return request'), {code: 'invalid-return'});
        }
        const record = await returns.create(input.returnRequest);
        const refund = await wallet.refund({returnId: record.id, amount: record.refund, currency: 'KRW', metadata: input.returnRequest.metadata});
        try {
          await inventory.restock({sku: input.returnRequest.sku, quantity: input.returnRequest.quantity, returnId: record.id});
          return {record, refund, restockPending: false, restockError: null};
        } catch (restockError) {
          throw restockError;
        }
      });
    },
  };
}

import {createSession} from '../shared/session.mjs';
import {createClient} from '../shared/http.mjs';
import {createInflight} from '../shared/inflight.mjs';
import {createOrderRepository} from '../data/orders.mjs';
import {createInventoryRepository} from '../data/inventory.mjs';
import {createReturnRepository} from '../data/returns.mjs';
import {createWalletRepository} from '../data/wallet.mjs';
import {createOrders} from './orders.mjs';
import {createInventory} from './inventory.mjs';
import {createReturns} from './returns.mjs';
import {createWallet} from './wallet.mjs';
import {createCheckout} from './checkout.mjs';
import {createRefundFlow} from './refund.mjs';
export function createSystem({transport, onUnauthorized, initialToken = null}) {
  const session = createSession(initialToken);
  const client = createClient({transport, onUnauthorized, session});
  const inflight = createInflight();
  const orders = createOrders({repository: createOrderRepository({client}), session});
  const inventory = createInventory({repository: createInventoryRepository({client}), session});
  const returns = createReturns({repository: createReturnRepository({client}), session});
  const wallet = createWallet({repository: createWalletRepository({client}), session});
  const checkout = createCheckout({orders, inventory, wallet, inflight});
  const refund = createRefundFlow({returns, inventory, wallet, inflight});
  function switchToken(token) {
    session.setToken(token);
    for (const resource of [orders, inventory, returns, wallet]) void resource;
  }
  return {orders, inventory, returns, wallet, checkout, refund, login: token => switchToken(token), logout: () => switchToken(null)};
}
